import org.jsoup.nodes.Document;
import org.junit.Assert;
import org.junit.Test;

public class TextNodeTest {

	private static final Document.OutputSettings outputSettings = new Document.OutputSettings();

    @Test
    public void textTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.text());
    }

    @Test
    public void textNewTextTest() {
        TextNode textNode = new TextNode("old text");
        String newText = "new text";
        textNode.text(newText);
        Assert.assertEquals(newText, textNode.text());
    }

    @Test
    public void nodeNameTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void getWholeTextTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.getWholeText());
    }

    @Test
    public void isBlankTestNotEmpty() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        Assert.assertFalse(textNode.isBlank());
    }

    @Test
    public void isBlankTestEmpty() {
        String text = "";
        TextNode textNode = new TextNode(text);
        Assert.assertTrue(textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        TextNode splitNode = textNode.splitText(5);
        Assert.assertEquals(text.substring(5), splitNode.text());
        Assert.assertEquals(text.substring(0, 5), textNode.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException { 
        String text = "example text";
        TextNode textNode = new TextNode(text); 
        StringBuilder accum = new StringBuilder(); 
        textNode.outerHtmlHead(accum, 0, outputSettings);
        Assert.assertEquals(text, accum.toString());
    }

    @Test
    public void outerHtmlTailTest() throws IOException {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        StringBuilder accum = new StringBuilder();
        textNode.outerHtmlTail(accum, 0, outputSettings);
        Assert.assertEquals("", accum.toString()); // tail method should not append anything
    }

    @Test
    public void cloneTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        TextNode clone = textNode.clone();
        Assert.assertEquals(textNode.text(), clone.text());
        Assert.assertFalse(textNode == clone);
    }

    @Test
    public void createFromEncodedTest() {
        String encodedText = "&#x20AC;";
        TextNode textNode = TextNode.createFromEncoded(encodedText, false);
        Assert.assertEquals("\u20AC", textNode.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String notNormalizedText = "example    text";
        String normalizedText = TextNode.normaliseWhitespace(notNormalizedText);
        Assert.assertEquals(normalizedText, "example text");
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "    example text";
        String strippedText = TextNode.stripLeadingWhitespace(text);
        Assert.assertEquals(strippedText, "example text");
    }

    @Test
    public void lastCharIsWhitespaceTestWhitespace() {
        StringBuilder textWithWhitespace = new StringBuilder("example text ");
        boolean isWhitespace = TextNode.lastCharIsWhitespace(textWithWhitespace);
        Assert.assertTrue(isWhitespace);
    }

    @Test
    public void lastCharIsWhitespaceTestNotWhitespace() {
        StringBuilder textWithoutWhitespace = new StringBuilder("example text");
        boolean isWhitespace = TextNode.lastCharIsWhitespace(textWithoutWhitespace);
        Assert.assertFalse(isWhitespace);
    }

    @Test
    public void toStringTest() {
        String text = "example text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.toString());
    }
}
